 const s=await setup();await confirm(s);await closePerformanceCycle(s);await performanceGrant(s.f.company);await performanceGrant(s.f.company,'draining');vi.stubEnv('ERPX_PEOPLE_PACKAGE_ENFORCEMENT','enforced');
 try{const cycle=(await evaluationWorkspace(s.f.owner,{year:2026})).definitions.find(row=>row.id===s.cycle.id);if(!cycle)throw Error('Actual reviewed closed cycle required');const image=()=>Promise.all(['hr_evaluation_definitions','hr_evaluation_definition_history','hr_evaluation_assessments','hr_evaluation_assessment_history'].map(async table=>(await db.prepare(`SELECT to_jsonb(row)::text image FROM ${table} row WHERE company_id=? ORDER BY to_jsonb(row)::text`).bind(s.f.company).all()).results)),before=await image();
  for(const phase of ['immediate','deferred'] as const){const command=key(),fault=`evaluation_reclose_${key().replaceAll('-','')}`;await db.exec(`CREATE FUNCTION ${fault}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN UPDATE hr_evaluation_assessments SET status='draft',confirmed_by=NULL,version=version+1 WHERE id='${s.assessment.id}';RETURN NEW;END $$;CREATE ${phase==='deferred'?'CONSTRAINT ':''}TRIGGER ${fault} AFTER INSERT ON audit_events ${phase==='deferred'?'DEFERRABLE INITIALLY DEFERRED ':''}FOR EACH ROW WHEN(NEW.command_id='${command}') EXECUTE FUNCTION ${fault}()`);try{await expect(saveEvaluationDefinition(s.f.owner,{id:cycle.id,kind:'cycle',expectedVersion:cycle.version,data:{...cycle.data,status:'closed'},reason:'All retained review duties must stay complete through closure'},command)).rejects.toMatchObject({code:'PERFORMANCE_CYCLE_OBLIGATIONS_REMAIN'});}finally{await db.exec(`DROP TRIGGER ${fault} ON audit_events;DROP FUNCTION ${fault}()`);}expect(await image()).toEqual(before);for(const table of ['command_receipts','audit_events','outbox_events'])expect(await db.prepare(`SELECT 1 FROM ${table} WHERE command_id=?`).bind(command).first()).toBeNull();expect((await performanceSettlement(s.f.company)).total).toBe(0);}
 }finally{vi.unstubAllEnvs();}
